mapper.select:
select pest_board_id from tb_pest_board


        and site_route like concat('',#{monitorCondition.pidRoute}, '%');


        and site_type = #{monitorCondition.siteType}


order by site_route,site_x,site_y,site_z

select pest_board_id pestBoardId,gather_site gatherSite , gather_time gatherTime ,beetle_count beetleCount,

    mealworm_count mealwormCount

alert_level alertLevel from tb_pest_data_history where pest_board_id = #{pestDataDto.pestBoardId}

    and gather_time >= #{pestDataDto.beginTime}


    and gather_time  <= #{pestDataDto.endTime}
